import {RAIN_NOTEBOOK_SCALE,RAIN_NOTEBOOK_UNIT,RAIN_NOTEBOOK_QUANTITIES,rainNotebookRows} from './rain-notebook-content.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function rainNotebookPending(s){return s.selected.some(id=>{const text=s.pending.bars[id].trim(),value=text===''?null:/^(?:0|[1-9]\d?)$/.test(text)&&Number(text)<=24?Number(text):NaN;return value!==s.values[id];});}
export function rainNotebookChartArt(s){if(!s)return '';const rows=rainNotebookRows(s.source),chosen=s.selected.map(id=>rows.find(r=>r.id===id)),quantity=RAIN_NOTEBOOK_QUANTITIES.find(q=>q.id===s.quantity)?.label||'Not chosen yet',description=`Your draft chart. ${quantity}. Unit: ${RAIN_NOTEBOOK_UNIT}. `+chosen.map((r,i)=>`${i===0?'First':'Second'} bar, ${r.label}: ${s.values[r.id]===null?'blank, no number yet':s.values[r.id]+' model-water tokens'}`).join('. ');
 if(!chosen.length)return '<div class="rn-empty-chart"><p>No rows selected yet.</p><p>Choose up to two source rows on Data. A missing row is not zero.</p></div>';
 return `<figure class="rn-chart"><figcaption><strong>Your draft chart</strong><span>${esc(quantity)} · ${RAIN_NOTEBOOK_UNIT}</span></figcaption><svg viewBox="0 0 480 285" role="img" aria-label="${esc(description)}"><rect width="480" height="285" fill="#fffef9"/>${RAIN_NOTEBOOK_SCALE.ticks.map(n=>`<path d="M${60+n*15} 24V225" stroke="${n===0?'#183f39':'#cad9df'}" stroke-width="${n===0?2:1}"/><text x="${60+n*15}" y="246" text-anchor="middle" fill="#183f39" font-size="16">${n}</text>`).join('')}<path d="M60 225H420" stroke="#183f39" stroke-width="2"/>${chosen.map((r,i)=>{const n=s.values[r.id],y=65+i*90;return `<text x="60" y="${y-15}" fill="#183f39" font-size="16">${esc(r.label)}</text>${n===null?`<text x="70" y="${y+18}" fill="#735745" font-size="16">Blank: no number yet</text>`:n===0?`<circle cx="60" cy="${y+12}" r="4" fill="#526b7f"/><text x="72" y="${y+18}" fill="#183f39" font-size="16">0</text>`:`<rect x="60" y="${y}" width="${n*15}" height="30" rx="2" fill="${i===0?'#526b7f':'#397958'}"/><text x="${Math.min(452,70+n*15)}" y="${y+21}" fill="#183f39" font-size="16">${n}</text>`}`;}).join('')}<text x="240" y="273" text-anchor="middle" fill="#183f39" font-size="15">${RAIN_NOTEBOOK_UNIT} · scale starts at 0</text></svg><p class="rn-pending-notice" ${rainNotebookPending(s)?'':'hidden'}>Typed entries are waiting for Set bar. The chart still shows the last numbers you set.</p><p class="rn-small">${esc(description)}. These bars show the numbers you set. The tray table does not change.</p></figure>`;
}
